'use strict';let SEOUL_VOLUME=[{m:'3월',v:5515},{m:'4월',v:8661},{m:'5월',v:8972},{m:'6월',v:5303},{m:'7월',v:5838},{m:'8월',v:3143,p:true}];function renderVolume(){const el=document.querySelector('#volumeChart');if(!el)return;const max=Math.max(...SEOUL_VOLUME.map(x=>x.v));el.innerHTML=SEOUL_VOLUME.map(x=>'<div class="vbar '+(x.p?'provisional':'')+'" style="height:'+Math.max(4,x.v/max*88)+'%"><strong>'+x.v.toLocaleString()+'</strong><label>'+x.m+(x.p?'*':'')+'</label></div>').join('')}renderVolume();const eok=n=>n==null?'—':(Number(n)/10000).toLocaleString('ko-KR',{maximumFractionDigits:2})+'억';const KB_HISTORY=[{d:'2026-09-05',avg:198849,n:43},{d:'2026-09-11',avg:190818,n:11}];function renderKbHistory(){const a=KB_HISTORY;if(!a.length)return;const vals=a.map(x=>x.avg),lo=Math.floor((Math.min(...vals)-10000)/10000)*10000,hi=Math.ceil((Math.max(...vals)+10000)/10000)*10000,range=Math.max(1,hi-lo);document.querySelector('#kbYAxis').innerHTML=[hi,hi-(range/3),hi-(range*2/3),lo].map(v=>'<b>'+eok(v)+'</b>').join('');const pts=a.map((x,i)=>{const px=a.length===1?210:i*420/(a.length-1),py=160-((x.avg-lo)/range)*150;return px.toFixed(1)+','+py.toFixed(1)}).join(' ');document.querySelector('#kbSvg').innerHTML='<line x1="0" y1="10" x2="420" y2="10"/><line x1="0" y1="60" x2="420" y2="60"/><line x1="0" y1="110" x2="420" y2="110"/><line x1="0" y1="160" x2="420" y2="160"/><polyline class="mainline" points="'+pts+'"/>'+a.map((x,i)=>{const px=a.length===1?210:i*420/(a.length-1),py=160-((x.avg-lo)/range)*150;return '<circle cx="'+px+'" cy="'+py+'" r="4" fill="#1677ff"/>'}).join('');document.querySelector('#kbXAxis').innerHTML=a.map(x=>'<span>'+x.d.slice(5).replace('-','/')+'</span>').join('');document.querySelector('#kbHistoryNote').textContent='DB 실데이터 '+a.length+'회 · '+a[0].d+' ~ '+a[a.length-1].d+' · 표본 '+a.map(x=>x.n+'건').join(' / ')};renderKbHistory();const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const signal=x=>{const d=Number(x.sale_listing_week_delta||0),t=x.recent_trade_manwon&&x.avg_ask_manwon?Number(x.recent_trade_manwon)-Number(x.avg_ask_manwon):0;if(d>0&&t<0)return['하락','down'];if(d<0&&t>=0)return['상승','up'];return['관찰','watch']};async function load(){const [m,k]=await Promise.all([fetch('buy_watchlist_market.json?v='+Date.now(),{cache:'no-store'}).then(r=>r.json()),fetch('buy_watchlist_master.json?v='+Date.now(),{cache:'no-store'}).then(r=>r.json())]);const market=m.items||[],master=k.items||[];document.querySelector('#updated').textContent='KB '+new Date(k.kb_collected_at||Date.now()).toLocaleDateString('ko-KR')+' · MARKET '+new Date(m.collected_at||Date.now()).toLocaleDateString('ko-KR');document.querySelector('#marketDate').textContent=new Date(m.collected_at||Date.now()).toLocaleDateString('ko-KR');const kb=new Map(master.map(x=>[Number(x.complex_id),Math.min(...(x.types||[]).map(t=>Number(t.general_price_manwon)).filter(Boolean))]));const boundary=[...master].map(x=>({name:x.user_name||x.kb_name,p:kb.get(Number(x.complex_id))})).filter(x=>x.p&&x.p>=130000&&x.p<=170000).sort((a,b)=>Math.abs(a.p-150000)-Math.abs(b.p-150000)).slice(0,7);document.querySelector('#boundary').innerHTML=boundary.map(x=>'<div class="row"><span>'+esc(x.name)+'</span><b class="'+(x.p<=150000?'up':'')+'">'+eok(x.p)+'</b></div>').join('')||'<small>13~17억 구간 데이터 없음</small>';const radar=[...market].filter(x=>x.sale_listing_week_delta!=null).sort((a,b)=>Math.abs(Number(b.sale_listing_week_delta))-Math.abs(Number(a.sale_listing_week_delta))).slice(0,7);document.querySelector('#radar').innerHTML=radar.map(x=>'<div class="radar-row"><span>'+esc(x.name)+'</span><b class="'+(x.sale_listing_week_delta>0?'down':x.sale_listing_week_delta<0?'up':'')+'">'+(x.sale_listing_week_delta>0?'+':'')+Number(x.sale_listing_week_delta)+'건</b></div>').join('');const rows=[...market].sort((a,b)=>Math.abs(Number(b.sale_listing_week_delta||0))-Math.abs(Number(a.sale_listing_week_delta||0)));document.querySelector('#summary').textContent='총 '+master.length+'개 관심단지 · KB · 호가 · 실거래 · 매물';document.querySelector('#body').innerHTML=rows.map(x=>{const s=signal(x);return'<tr><td><b>'+esc(x.name)+'</b></td><td>'+eok(kb.get(Number(x.complex_id)))+'</td><td>'+eok(x.recent_trade_manwon)+'<small> '+esc(x.recent_trade_date||'')+'</small></td><td>'+eok(x.avg_ask_manwon)+'</td><td>'+Number(x.sale_listing_count||0).toLocaleString()+'건</td><td class="'+(x.sale_listing_week_delta>0?'down':x.sale_listing_week_delta<0?'up':'')+'">'+(x.sale_listing_week_delta>0?'+':'')+Number(x.sale_listing_week_delta||0)+'건</td><td><span class="pill '+s[1]+'">'+s[0]+'</span></td></tr>'}).join('');document.querySelector('#mobileCards').innerHTML=rows.map(x=>{const s=signal(x);return'<article class="complex"><div class="complex-head"><b>'+esc(x.name)+'</b><span class="pill '+s[1]+'">'+s[0]+'</span></div><div class="complex-grid"><div><span>KB시세</span><b>'+eok(kb.get(Number(x.complex_id)))+'</b></div><div><span>최근 실거래</span><b>'+eok(x.recent_trade_manwon)+'</b></div><div><span>매물 평균</span><b>'+eok(x.avg_ask_manwon)+'</b></div><div><span>매매 매물</span><b>'+Number(x.sale_listing_count||0)+'건</b></div><div><span>전주 대비</span><b class="'+(x.sale_listing_week_delta>0?'down':x.sale_listing_week_delta<0?'up':'')+'">'+(x.sale_listing_week_delta>0?'+':'')+Number(x.sale_listing_week_delta||0)+'건</b></div><div><span>최근 거래일</span><b>'+esc(x.recent_trade_date||'—')+'</b></div></div></article>'}).join('')+'<button id="moreComplexes" class="more-btn">↓ 더보기 ('+Math.max(0,rows.length-5)+'개)</button>';const mc=document.querySelector('#mobileCards'),mb=document.querySelector('#moreComplexes');if(rows.length<=5)mb.style.display='none';mb.addEventListener('click',()=>{const open=mc.classList.toggle('expanded');mb.textContent=open?'↑ 접기':'↓ 더보기 ('+Math.max(0,rows.length-5)+'개)'})}load().catch(e=>{document.querySelector('#updated').textContent='DATA ERROR';console.error(e)});
async function loadMarketIndicators(){
 try{
  const d=await fetch('market_indicators.json?v='+Date.now(),{cache:'no-store'}).then(r=>r.json());
  if(d.seoul_apt_trade_count?.length){
   SEOUL_VOLUME=d.seoul_apt_trade_count.map(x=>({m:Number(x[0].slice(5))+'월',v:x[1],p:x[2]}));renderVolume();
  }
  const fresh=document.querySelector('.fresh');
  if(fresh&&d.updated_at) fresh.insertAdjacentHTML('beforeend','<div><b>시장지표 파일</b><span>'+d.updated_at+' 갱신</span></div>');
 }catch(e){}
}
loadMarketIndicators();
const BASE_RATES=[{d:'2024-10-11',v:3.25},{d:'2024-11-28',v:3.00},{d:'2025-02-25',v:2.75},{d:'2025-05-29',v:2.50},{d:'2026-07-16',v:2.75},{d:'2026-08-27',v:3.00}];function renderRateDetail(){const a=BASE_RATES,lo=2.25,hi=3.50,w=620,h=220;document.querySelector('#rateY').innerHTML=['3.50%','3.25%','3.00%','2.75%','2.50%','2.25%'].map(x=>'<span>'+x+'</span>').join('');const pts=a.map((x,i)=>[i*w/(a.length-1),h-((x.v-lo)/(hi-lo))*h]);document.querySelector('#rateSvg').innerHTML='<polyline points="'+pts.map(p=>p.join(',')).join(' ')+'"/>'+pts.map((p,i)=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="5"/><text x="'+p[0]+'" y="'+(p[1]-10)+'" text-anchor="middle">'+a[i].v.toFixed(2)+'</text>').join('');document.querySelector('#rateX').innerHTML=a.map(x=>'<span>'+x.d.slice(2,7).replace('-','.')+'</span>').join('');document.querySelector('#rateHistory').innerHTML='<div class="head"><span>변경일</span><b>기준금리</b><em>직전 대비</em></div>'+a.slice().reverse().map(x=>{const n=a.indexOf(x),p=n? a[n-1].v:null,delta=p==null?'—':((x.v-p)>0?'+':'')+(x.v-p).toFixed(2)+'%p';return '<div><span>'+x.d+'</span><b>'+x.v.toFixed(2)+'%</b><em>'+delta+'</em></div>'}).join('')}const rc=document.querySelector('#rateCard'),rd=document.querySelector('#rateDetail');function openRate(){rd.hidden=false;rc.setAttribute('aria-expanded','true');renderRateDetail();rd.scrollIntoView({behavior:'smooth',block:'start'})}rc?.addEventListener('click',openRate);rc?.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openRate()}});document.querySelector('#closeRate')?.addEventListener('click',()=>{rd.hidden=true;rc.setAttribute('aria-expanded','false')});
const MACRO={
 m2:{title:'한국 M2 통화공급 증가율',source:'한국은행 · 월간 공표',unit:'%',current:'8.00%',series:[['2026-03',7.3],['2026-04',8.2],['2026-05',7.0],['2026-06',8.2],['2026-07',9.2],['2026-08',9.4],['2026-09',8.0]]},
 fed:{title:'미국 연준 기준금리',source:'Federal Reserve · FOMC',unit:'%',current:'3.75~4.00%',series:[['2025-12',3.75],['2026-01',3.75],['2026-03',3.75],['2026-04',3.75],['2026-06',3.75],['2026-07',3.75],['2026-09',4.00]]}
};
function showMacro(k){const z=MACRO[k],a=z.series,vals=a.map(x=>x[1]),lo=Math.max(0,Math.floor((Math.min(...vals)-.5)*2)/2),hi=Math.ceil((Math.max(...vals)+.5)*2)/2,range=hi-lo,w=620,h=220;document.querySelector('#macroTitle').textContent=z.title;document.querySelector('#macroSource').textContent=z.source;document.querySelector('#macroCurrent').innerHTML='<div><span>현재</span><b>'+z.current+'</b></div><small>최신 공표 기준</small>';document.querySelector('#macroY').innerHTML=[hi,hi-range/4,hi-range/2,hi-range*3/4,lo].map(v=>'<span>'+v.toFixed(2)+'%</span>').join('');const pts=a.map((x,i)=>[i*w/(a.length-1),h-((x[1]-lo)/range)*h]);document.querySelector('#macroSvg').innerHTML='<polyline points="'+pts.map(p=>p.join(',')).join(' ')+'"/>'+pts.map((p,i)=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="5"/><text x="'+p[0]+'" y="'+(p[1]-10)+'" text-anchor="middle">'+a[i][1].toFixed(2)+'</text>').join('');document.querySelector('#macroX').innerHTML=a.map(x=>'<span>'+x[0].slice(2).replace('-','.')+'</span>').join('');document.querySelector('#macroHistory').innerHTML='<div class="head"><span>기간</span><b>발표</b><em>직전</em></div>'+a.slice().reverse().map((x,i,r)=>{const n=a.indexOf(x),p=n?a[n-1][1]:null;return '<div><span>'+x[0]+'</span><b>'+x[1].toFixed(2)+'%</b><em>'+(p==null?'—':p.toFixed(2)+'%')+'</em></div>'}).join('');const el=document.querySelector('#macroDetail');el.hidden=false;el.scrollIntoView({behavior:'smooth',block:'start'})}
document.querySelector('#m2Card')?.addEventListener('click',()=>showMacro('m2'));document.querySelector('#fedCard')?.addEventListener('click',()=>showMacro('fed'));document.querySelector('#closeMacro')?.addEventListener('click',()=>document.querySelector('#macroDetail').hidden=true);

const RELEASES={m2:[{date:'2026-10-15',label:'8월 통화 및 유동성'},{date:'2026-11-13',label:'9월 통화 및 유동성'}],fed:[{date:'2026-10-28',label:'FOMC 금리결정'},{date:'2026-12-09',label:'FOMC 금리결정'}]};
function nextRelease(kind){const today=new Date(),a=RELEASES[kind],n=a.find(x=>new Date(x.date+'T23:59:59')>=today)||a[a.length-1];return n}
function renderReleaseSchedule(){const m=nextRelease('m2'),f=nextRelease('fed');const me=document.querySelector('#m2Next'),fe=document.querySelector('#fedNext');if(me)me.textContent='다음 발표 '+m.date.replaceAll('-','.')+' · '+m.label;if(fe)fe.textContent='다음 FOMC '+f.date.replaceAll('-','.')+' · '+f.label}
renderReleaseSchedule();
